                  {copied
                    ? t('admin.operations.monitor.copied')
                    : t('admin.operations.monitor.copyToken')}
                </Button>
              </div>
              <p className="text-xs text-muted-foreground">
                {t('admin.operations.monitor.wallHint')}
              </p>
            </div>
          )}

