      <p className="text-xs text-muted-foreground">{t('admin.servers.scaleHint')}</p>

      {!scale ? null : !scale.configured ? (
        <p className="rounded-lg border border-border p-2 text-xs">
          {t('admin.servers.scaleNotConfigured')}
        </p>
      ) : (
        <form
          className="flex flex-wrap items-end gap-2"
          onSubmit={(event) => {
            event.preventDefault()
            setScale.mutate(Number(count))
          }}
        >
          {scale.count !== null ? (
            <p className="w-full text-sm">{t('admin.servers.scaleCurrent', { n: scale.count })}</p>
          ) : null}
          <label className="space-y-1">
            <span className="block text-xs text-muted-foreground">
              {t('admin.servers.scaleNew', { max: scale.max })}
            </span>
            <Input
              type="number"
              min={1}
              max={scale.max}
              step={1}
              value={count}
              onChange={(event) => setCount(event.target.value)}
              className="w-32"
            />
          </label>
          <Button
            type="submit"
            disabled={setScale.isPending || !count || Number(count) === scale.count}
          >
            {t('admin.servers.scaleApply')}
          </Button>
        </form>
      )}

      {setScale.isSuccess ? (
        <p role="status" className="text-xs text-[hsl(var(--color-success))]">
          {t('admin.servers.scaleDone')}
        </p>
      ) : null}
      {setScale.isError ? (
        <p role="alert" className="text-xs text-destructive">
          {t('admin.servers.scaleError')}{' '}
          {(setScale.error as { response?: { data?: { detail?: string } } }).response?.data
            ?.detail || apiErrorMessage(setScale.error, t('admin.error.generic'))}
        </p>
      ) : null}
    </Card>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { useTranslations } from 'next-intl'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { apiClient, apiErrorMessage } from '@hisabche/api'

import { Button, Card, Input } from '@/components/ui'

/**
 * Plan limits ΓÇö per plan, and per workspace (which wins).
 *
 *   GET/PUT /admin/plan-limits[/:plan]
 *   GET/PUT /admin/workspace-limits/:workspaceId
 *
 * A field left EMPTY is not sent: that layer inherits. ┬½Unlimited┬╗ sends null.
 * AI questions cannot be unlimited ΓÇö the server refuses it too.
 */
type Key = 'invoices' | 'users' | 'aiMonthly'
const KEYS: Key[] = ['invoices', 'users', 'aiMonthly']
type Values = Partial<Record<Key, number | null>>
interface PlanRow {
  plan: string
  defaults: Record<Key, number | null>
  settings: Values
}

/** Form state per field: '' = inherit, 'unlimited', or a number as text. */
type Field = string

function toFields(values: Values): Record<Key, Field> {
  const out = {} as Record<Key, Field>
  for (const key of KEYS) {
    const v = values[key]
    out[key] = v === undefined ? '' : v === null ? 'unlimited' : String(v)
  }
  return out
}

function toPatch(fields: Record<Key, Field>): Values {
  const out: Values = {}
  for (const key of KEYS) {
    const f = fields[key].trim()
    if (f === '') continue
    out[key] = f === 'unlimited' ? null : Number(f)
  }
  return out
}

function LimitFields({
  fields,
  onChange,
  defaults,
}: {
  fields: Record<Key, Field>
  onChange: (next: Record<Key, Field>) => void
  defaults?: Record<Key, number | null> | undefined
}) {
  const t = useTranslations()
  return (
    <div className="grid gap-3 sm:grid-cols-3">
      {KEYS.map((key) => (
        <label key={key} className="space-y-1 text-sm">
          <span className="block text-xs text-muted-foreground">{t(`admin.limits.${key}`)}</span>
          <Input
            type="number"
            min={0}
            step={1}
            disabled={fields[key] === 'unlimited'}
            value={fields[key] === 'unlimited' ? '' : fields[key]}
            placeholder={
              defaults
                ? t('admin.limits.default', {
                    value:
                      defaults[key] === null
                        ? t('admin.limits.unlimitedValue')
                        : String(defaults[key]),
                  })
                : ''
            }
            onChange={(event) => onChange({ ...fields, [key]: event.target.value })}
          />
          {key !== 'aiMonthly' ? (
            <span className="flex items-center gap-1.5 text-xs">
              <input
                type="checkbox"
                checked={fields[key] === 'unlimited'}
                onChange={(event) =>
                  onChange({ ...fields, [key]: event.target.checked ? 'unlimited' : '' })
                }
              />
              {t('admin.limits.unlimited')}
            </span>
          ) : null}
        </label>
      ))}
    </div>
  )
}

function PlanRowEditor({ row }: { row: PlanRow }) {
  const t = useTranslations()
  const queryClient = useQueryClient()
  const [fields, setFields] = useState(() => toFields(row.settings))
  useEffect(() => setFields(toFields(row.settings)), [row.settings])
  const save = useMutation({
    mutationFn: async () => {
      await apiClient.put(`/admin/plan-limits/${row.plan}`, toPatch(fields))
    },
    onSuccess: () => void queryClient.invalidateQueries({ queryKey: ['admin', 'plan-limits'] }),
  })
  return (
    <form
      className="space-y-2 rounded-xl border border-border p-3"
      onSubmit={(event) => {
        event.preventDefault()
        save.mutate()
      }}
    >
      <h3 className="text-sm font-medium">{t(`admin.plan.${row.plan}`)}</h3>
      <LimitFields fields={fields} onChange={setFields} defaults={row.defaults} />
      <div className="flex items-center gap-2">
        <Button type="submit" disabled={save.isPending}>
          {t('admin.limits.save')}
        </Button>
        {save.isSuccess ? (
          <span className="text-xs text-emerald-500">{t('admin.limits.saved')}</span>
        ) : null}
        {save.isError ? (
          <span role="alert" className="text-xs text-destructive">
            {apiErrorMessage(save.error, t('admin.error.generic'))}
          </span>
        ) : null}
      </div>
    </form>
  )
}

export function PlanLimitsPanel() {
  const t = useTranslations()
  const { data } = useQuery({
    queryKey: ['admin', 'plan-limits'],
    queryFn: async ({ signal }) => {
      const { data: body } = await apiClient.get('/admin/plan-limits', { signal })
      return body as { configured: boolean; plans: PlanRow[] }
    },
  })

  return (
    <Card className="space-y-3 p-4" data-plan-limits="">
      <h2 className="text-sm font-semibold">{t('admin.limits.title')}</h2>
      <p className="text-xs text-muted-foreground">{t('admin.limits.hint')}</p>
      {data && !data.configured ? (
        <p className="rounded-lg border border-amber-500/40 bg-amber-500/10 p-2 text-xs">
          {t('admin.limits.notConfigured')}
        </p>
      ) : null}
      {data?.plans.map((row) => (
        <PlanRowEditor key={row.plan} row={row} />
      ))}
      <WorkspaceLimits />
    </Card>
  )
}

function WorkspaceLimits() {
  const t = useTranslations()
  const [workspaceId, setWorkspaceId] = useState('')
  const [loaded, setLoaded] = useState<string | null>(null)
  const [fields, setFields] = useState(() => toFields({}))
  const [note, setNote] = useState('')

  const load = useMutation({
    mutationFn: async (id: string) => {
      const { data } = await apiClient.get(`/admin/workspace-limits/${id}`)
      return data as { limits: Values; note: string | null }
    },
    onSuccess: (data, id) => {
      setFields(toFields(data.limits))
      setNote(data.note ?? '')
      setLoaded(id)
    },
  })
  const save = useMutation({
    mutationFn: async () => {
      await apiClient.put(`/admin/workspace-limits/${loaded}`, { limits: toPatch(fields), note })
    },
  })

  return (
    <div className="space-y-2 rounded-xl border border-dashed border-border p-3">
      <h3 className="text-sm font-medium">{t('admin.limits.workspaceTitle')}</h3>
      <p className="text-xs text-muted-foreground">{t('admin.limits.workspaceHint')}</p>
      <div className="flex flex-wrap gap-2">
        <Input
          dir="ltr"
          value={workspaceId}
          onChange={(event) => setWorkspaceId(event.target.value)}
          placeholder="00000000-0000-0000-0000-000000000000"
          className="w-80 font-mono"
        />
        <Button
          type="button"
          variant="outline"
          disabled={!workspaceId.trim() || load.isPending}
          onClick={() => load.mutate(workspaceId.trim())}
        >
          {t('admin.limits.load')}
        </Button>
      </div>
      {loaded ? (
        <form
          className="space-y-2"
          onSubmit={(event) => {
            event.preventDefault()
            save.mutate()
          }}
        >
          <LimitFields fields={fields} onChange={setFields} />
          <label className="block space-y-1 text-sm">
            <span className="block text-xs text-muted-foreground">{t('admin.limits.note')}</span>
            <Input value={note} maxLength={500} onChange={(event) => setNote(event.target.value)} />
          </label>
          <div className="flex items-center gap-2">
            <Button type="submit" disabled={save.isPending}>
              {t('admin.limits.save')}
            </Button>
            {save.isSuccess ? (
              <span className="text-xs text-emerald-500">{t('admin.limits.saved')}</span>
            ) : null}
            {save.isError ? (
              <span role="alert" className="text-xs text-destructive">
                {apiErrorMessage(save.error, t('admin.error.generic'))}
              </span>
            ) : null}
          </div>
        </form>
      ) : null}
      {load.isError ? (
        <p role="alert" className="text-xs text-destructive">
          {apiErrorMessage(load.error, t('admin.error.generic'))}
        </p>
      ) : null}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useTranslations } from 'next-intl'
import { usePathname, useRouter } from 'next/navigation'
import {
  Button,
  Card,
  EmptyState,
  Input,
  PaginationBar,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Skeleton,
} from '@/components/ui'

import { ErrorState } from '@/components/admin-shell/admin-ui'
import { cn } from '@/lib/utils'
import { useAdminSession } from '@/hooks/use-admin-session'
import {
  PLANS,
  STATUSES,
  daysUntilExpiry,
  useAdminSubscriptions,
  useUpdateSubscriptionPlan,
  useUpdateSubscriptionStatus,
  type AdminSubscription,
  type Plan,
  type SubscriptionStatus,
} from '@/hooks/use-admin-subscriptions'
import { UpgradeRequestsPanel } from './upgrade-requests-panel'
import { PlanLimitsPanel } from './plan-limits-panel'
import { useAdminLocale } from '@/hooks/use-admin-locale'
import { adminDate } from '@/lib/admin-format'

const PAGE_SIZE = 20

/** Rows within this many days of expiry are highlighted, never filtered. */
const EXPIRING_SOON_DAYS = 7

const STATUS_TONE: Record<SubscriptionStatus, string> = {
  active: 'bg-[hsl(var(--color-success))]',
  trial: 'bg-[hsl(var(--fg-tertiary))]',
  expired: 'bg-[hsl(var(--color-destructive))]',
  cancelled: 'bg-[hsl(var(--fg-tertiary))]',
  past_due: 'bg-[hsl(var(--color-warning))]',
}

export function SubscriptionsClient() {
  const t = useTranslations()
  const router = useRouter()
  const pathname = usePathname()
  const { error: authError } = useAdminSession()

  const [plan, setPlan] = useState<Plan | 'all'>('all')
  const [status, setStatus] = useState<SubscriptionStatus | 'all'>('all')
  const [page, setPage] = useState(0)
  const [reason, setReason] = useState('')

  const localePrefix = pathname.split('/').filter(Boolean)[0] || 'fa'

  const { data, isLoading, isError, isFetching, refetch } = useAdminSubscriptions({
    ...(plan !== 'all' ? { plan } : {}),
    ...(status !== 'all' ? { status } : {}),
    limit: PAGE_SIZE,
    offset: page * PAGE_SIZE,
  })

  const updatePlan = useUpdateSubscriptionPlan()
  const updateStatus = useUpdateSubscriptionStatus()

  if (authError) {
    return (
      <div className="space-y-4">
        <ErrorState
          message={authError === 'NO_SESSION' ? t('auth.sessionExpired') : t('app.error')}
          onRetry={() => router.replace(`/${localePrefix}/login`)}
        />
        <Button variant="outline" onClick={() => router.replace(`/${localePrefix}/login`)}>
          {t('auth.signIn')}
        </Button>
      </div>
    )
  }

  const subscriptions = data?.subscriptions ?? []
  const total = data?.total ?? 0

  const from = total === 0 ? 0 : page * PAGE_SIZE + 1
  const to = Math.min((page + 1) * PAGE_SIZE, total)

  return (
    <div className="space-y-6">
      {/* Paid plans are activated here, after payment ΓÇö never by the customer. */}
      <UpgradeRequestsPanel />
      <PlanLimitsPanel />

      <p className="rounded-2xl border border-[hsl(var(--color-warning)/0.4)] bg-[hsl(var(--color-warning)/0.1)] p-4 text-sm">
        {t('admin.subscriptions.noDateBuckets')}
      </p>

      {/* ΓöÇΓöÇ Filter row ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <div className="space-y-4">
        <div
          role="group"
          aria-label={t('admin.subscriptions.plan')}
          className="flex flex-wrap items-center gap-2"
        >
          <span className="me-1 text-sm text-muted-foreground">
            {t('admin.subscriptions.plan')}
          </span>
          <Button
            size="sm"
            variant={plan === 'all' ? 'default' : 'outline'}
            onClick={() => {
              setPlan('all')
              setPage(0)
            }}
          >
            {t('admin.subscriptions.allPlans')}
          </Button>
          {PLANS.map((p) => (
            <Button
              key={p}
              size="sm"
              variant={plan === p ? 'default' : 'outline'}
              onClick={() => {
                setPlan(p)
                setPage(0)
              }}
            >
              {t(`admin.plan.${p}`)}
            </Button>
          ))}
        </div>

        <div
          role="group"
          aria-label={t('admin.subscriptions.status')}
          className="flex flex-wrap items-center gap-2"
        >
          <span className="me-1 text-sm text-muted-foreground">
            {t('admin.subscriptions.status')}
          </span>
          <Button
            size="sm"
            variant={status === 'all' ? 'default' : 'outline'}
            onClick={() => {
              setStatus('all')
              setPage(0)
            }}
          >
            {t('admin.subscriptions.allStatuses')}
          </Button>
          {STATUSES.map((value) => (
            <Button
              key={value}
              size="sm"
              variant={status === value ? 'default' : 'outline'}
              onClick={() => {
                setStatus(value)
                setPage(0)
              }}
            >
              <span
                aria-hidden="true"
                className={cn('me-1.5 inline-block h-2 w-2 rounded-full', STATUS_TONE[value])}
              />
              {t(`admin.status.${value}`)}
            </Button>
          ))}
        </div>

        {/* The audit reason. */}
        <label className="flex max-w-xl flex-col gap-1.5 text-sm">
          <span className="text-muted-foreground">{t('admin.subscriptions.reason')}</span>
          <Input
            value={reason}
            onChange={(e) => setReason(e.target.value)}
            placeholder={t('admin.subscriptions.reasonHint')}
            className="h-11 rounded-xl"
          />
        </label>
      </div>

      {isLoading && (
        <div className="space-y-3">
          {Array.from({ length: 5 }, (_, i) => (
            <Skeleton key={i} className="h-28 w-full rounded-2xl" />
          ))}
        </div>
      )}

      {isError && !isLoading && (
        <ErrorState message={t('admin.subscriptions.loadError')} onRetry={() => void refetch()} />
      )}

      {!isLoading && !isError && subscriptions.length === 0 && (
        <EmptyState title={t('admin.subscriptions.empty')} />
      )}

      {(updatePlan.isError || updateStatus.isError) && (
        <p role="alert" className="text-sm text-destructive">
          {t('admin.subscriptions.updateError')}
        </p>
      )}

      {subscriptions.length > 0 && (
        <ul className="space-y-3">
          {subscriptions.map((subscription) => (
            <SubscriptionRow
              key={subscription.id}
              subscription={subscription}
              reason={reason}
              busy={
                (updatePlan.isPending &&
                  updatePlan.variables?.subscriptionId === subscription.id) ||
                (updateStatus.isPending &&
                  updateStatus.variables?.subscriptionId === subscription.id)
              }
              onPlan={(next) =>
                updatePlan.mutate({
                  subscriptionId: subscription.id,
                  plan: next,
                  ...(reason ? { reason } : {}),
                })
              }
              onStatus={(next) =>
                updateStatus.mutate({
                  subscriptionId: subscription.id,
                  status: next,
                  ...(reason ? { reason } : {}),
                })
              }
            />
          ))}
        </ul>
      )}

      <PaginationBar
        page={page}
        pageSize={PAGE_SIZE}
        total={total}
        busy={isFetching}
        onPage={setPage}
        showingLabel={t('admin.pagination.showing', { from, to, total })}
        previousLabel={t('admin.pagination.previous')}
        nextLabel={t('admin.pagination.next')}
      />
    </div>
  )
}

function SubscriptionRow({
  subscription,
  reason,
  busy,
  onPlan,
  onStatus,
}: {
  subscription: AdminSubscription
  reason: string
  busy: boolean
  onPlan: (plan: Plan) => void
  onStatus: (status: SubscriptionStatus) => void
}) {
  const dateLocale = useAdminLocale()
  const t = useTranslations()
  const days = daysUntilExpiry(subscription.period_end)

  const expired = days !== null && days < 0
  const expiringSoon = days !== null && days >= 0 && days <= EXPIRING_SOON_DAYS

  void reason

  return (
    <li
      className={cn(
        'flex flex-col gap-4 rounded-2xl border bg-card p-4 transition-colors lg:flex-row lg:items-center lg:justify-between',
        expired
          ? 'border-[hsl(var(--color-destructive)/0.4)]'
          : 'border-border hover:border-border-strong',
      )}
    >
      <div className="min-w-0 flex-1">
        <div className="flex flex-wrap items-center gap-2">
          <span className="inline-flex items-center rounded-full border border-[hsl(var(--color-primary)/0.4)] bg-[hsl(var(--color-primary)/0.15)] px-3 py-1 text-xs font-medium text-[hsl(var(--color-primary))]">
            {t(`admin.plan.${subscription.plan}`)}
          </span>
          <span className="inline-flex items-center gap-2 rounded-full border border-border bg-accent px-3 py-1 text-xs font-medium">
            <span
              aria-hidden="true"
              className={cn(
                'h-2 w-2 shrink-0 rounded-full',
                STATUS_TONE[subscription.status as SubscriptionStatus] ??
                  'bg-[hsl(var(--fg-tertiary))]',
              )}
            />
            {t(`admin.status.${subscription.status}`)}
          </span>
          {subscription.is_trial && (
            <span className="inline-flex items-center rounded-full border border-violet-500/40 bg-violet-500/15 px-3 py-1 text-xs font-medium text-violet-400">
              {t('admin.subscriptions.trial')}
            </span>
          )}
          {expired && (
            <span className="inline-flex items-center gap-2 rounded-full border border-[hsl(var(--color-destructive)/0.4)] bg-[hsl(var(--color-destructive)/0.15)] px-3 py-1 text-xs font-medium text-[hsl(var(--color-destructive))]">
              <span
                aria-hidden="true"
                className="h-2 w-2 shrink-0 rounded-full bg-[hsl(var(--color-destructive))]"
              />
              {t('admin.subscriptions.expired')}
            </span>
          )}
          {expiringSoon && (
            <span className="inline-flex items-center gap-2 rounded-full border border-[hsl(var(--color-warning)/0.4)] bg-[hsl(var(--color-warning)/0.15)] px-3 py-1 text-xs font-medium text-[hsl(var(--color-warning))]">
              <span
                aria-hidden="true"
                className="h-2 w-2 shrink-0 rounded-full bg-[hsl(var(--color-warning))]"
              />
              {t('admin.subscriptions.expiringSoon')}
            </span>
          )}
        </div>

        <div className="mt-1 text-sm text-muted-foreground">
          {t('admin.subscriptions.periodEnd')}:{' '}
          {subscription.period_end ? (
            <>
              <time dateTime={subscription.period_end} suppressHydrationWarning>
                {adminDate(subscription.period_end, dateLocale)}
              </time>
              {days !== null && (
                <span className="ms-2">
                  {days >= 0
                    ? t('admin.subscriptions.expiresIn', { days })
                    : t('admin.subscriptions.expiredAgo', { days: Math.abs(days) })}
                </span>
              )}
            </>
          ) : (
            t('admin.subscriptions.noPeriod')
          )}
        </div>

        {subscription.workspace_id && (
          <div className="mt-1 text-xs text-muted-foreground">
            {t('admin.subscriptions.workspaceId')}:{' '}
            <code dir="ltr" className="select-all font-mono" data-workspace-id="">
              {subscription.workspace_id}
            </code>
          </div>
        )}

        {!subscription.workspace_id && (
          <div className="mt-1 text-xs text-[hsl(var(--color-warning))]">
            {t('admin.workspaces.noOwner')}
          </div>
        )}
      </div>

      <div className="flex shrink-0 flex-col gap-2 sm:flex-row">
        <Select
          value={subscription.plan}
          disabled={busy}
          onValueChange={(v) => {
            if (v !== subscription.plan) onPlan(v as Plan)
          }}
        >
          <SelectTrigger
            className="h-11 w-40 rounded-xl"
            aria-label={t('admin.subscriptions.changePlan')}
          >
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {PLANS.map((p) => (
              <SelectItem key={p} value={p}>
                {t(`admin.plan.${p}`)}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        <Select
          value={subscription.status}
          disabled={busy}
          onValueChange={(v) => {
            if (v !== subscription.status) onStatus(v as SubscriptionStatus)
          }}
        >
          <SelectTrigger
            className="h-11 w-40 rounded-xl"
            aria-label={t('admin.subscriptions.changeStatus')}
          >
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {STATUSES.map((s) => (
              <SelectItem key={s} value={s}>
                {t(`admin.status.${s}`)}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
    </li>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { useTranslations } from 'next-intl'
import { Button, Card, CardContent, CardHeader, CardTitle, Input } from '@/components/ui'
import { createAdminSupabaseClient } from '@/lib/supabase-client'
import { useRouter, usePathname, useSearchParams } from 'next/navigation'

/**
 * Admin sign-in is two steps: password, then a TOTP code (Supabase MFA).
 *
 * `proxy.ts` refuses every admin page below AAL2, so an admin who had only
 * typed a password used to be bounced back here with nothing to type a code
 * into ΓÇö the panel had no way to enrol or verify a factor at all.
 *
 *   password  ΓåÆ signInWithPassword
 *   enroll    ΓåÆ first time: QR code + secret, the code from the app enrols it
 *   challenge ΓåÆ afterwards: the code from the app
 */
type Step =
  | { kind: 'password' }
  | { kind: 'enroll'; factorId: string; qrCode: string; secret: string }
  | { kind: 'challenge'; factorId: string }

export function LoginClient() {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const t = useTranslations()
  const [error, setError] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [step, setStep] = useState<Step>({ kind: 'password' })

  // proxy.ts redirects here with `?error=admin_required` when the credentials
  // were valid but the account is not in ADMIN_ALLOWED_EMAILS, and with
  // `?error=mfa_required` when the session has not passed a TOTP check.
  const reason = searchParams.get('error')

  const goToDashboard = () => {
    const localePrefix = pathname.split('/').filter(Boolean)[0] || 'fa'
    router.replace(`/${localePrefix}/dashboard`)
  }

  /** After the password: verified already ΓåÆ in; a TOTP factor ΓåÆ challenge; none ΓåÆ enrol. */
  const continueToSecondFactor = async () => {
    const supabase = createAdminSupabaseClient()
    const { data: assurance, error: aalError } =
      await supabase.auth.mfa.getAuthenticatorAssuranceLevel()
    if (aalError) throw aalError
    if (assurance?.currentLevel === 'aal2') {
      goToDashboard()
      return
    }

    const { data: factors, error: listError } = await supabase.auth.mfa.listFactors()
    if (listError) throw listError
    const verified = factors?.totp?.[0]
    if (verified) {
      setStep({ kind: 'challenge', factorId: verified.id })
      return
    }

    // A half-finished enrolment blocks a new one; remove it before starting again.
    for (const factor of factors?.all ?? []) {
      if (factor.factor_type === 'totp' && factor.status === 'unverified') {
        const { error: unenrollError } = await supabase.auth.mfa.unenroll({ factorId: factor.id })
        if (unenrollError) throw unenrollError
      }
    }
    const { data: enrolled, error: enrollError } = await supabase.auth.mfa.enroll({
      factorType: 'totp',
    })
    if (enrollError) throw enrollError
    setStep({
      kind: 'enroll',
      factorId: enrolled.id,
      qrCode: enrolled.totp.qr_code,
      secret: enrolled.totp.secret,
    })
  }

  const run = async (work: () => Promise<void>) => {
    setIsLoading(true)
    setError(null)
    try {
      await work()
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : t('app.error'))
    } finally {
      setIsLoading(false)
    }
  }

  const handleSignIn = (email: string, password: string) =>
    run(async () => {
      const supabase = createAdminSupabaseClient()
      const { error: signInError } = await supabase.auth.signInWithPassword({ email, password })
      if (signInError) throw signInError
      await continueToSecondFactor()
    })

  const handleVerify = (factorId: string, code: string) =>
    run(async () => {
      const supabase = createAdminSupabaseClient()
      const { error: verifyError } = await supabase.auth.mfa.challengeAndVerify({
        factorId,
        code: code.trim(),
      })
      if (verifyError) throw verifyError
      goToDashboard()
    })

  useEffect(() => {
    // An existing session goes on only as far as its own level allows.
    const supabase = createAdminSupabaseClient()
    void supabase.auth.getSession().then(async ({ data }) => {
      if (!data.session) return
      try {
        await continueToSecondFactor()
      } catch (e: unknown) {
        setError(e instanceof Error ? e.message : t('app.error'))
      }
    })
    // Once on mount; after that the forms drive the steps.
  }, [])

  const notice =
    reason === 'admin_required'
      ? t('adminPanel.notAllowed')
      : reason === 'mfa_required' && step.kind === 'password'
        ? t('adminPanel.mfaRequired')
        : null

  return (
    <div className="min-h-screen flex items-center justify-center bg-[hsl(var(--surface-base))] p-6">
      <Card className="w-full max-w-md">
        <CardHeader>
          <CardTitle className="text-center">
            {step.kind === 'password'
              ? t('adminPanel.access')
              : step.kind === 'enroll'
                ? t('adminPanel.mfaEnrollTitle')
                : t('adminPanel.mfaChallengeTitle')}
          </CardTitle>
        </CardHeader>
        <CardContent>
          {(error ?? notice) && (
            <div
              className="mb-4 text-sm text-[hsl(var(--color-destructive))] bg-[hsl(var(--color-destructive)/0.08)] border border-[hsl(var(--color-destructive)/0.2)] p-3 rounded-xl flex items-start gap-2"
              role="alert"
            >
              <span className="shrink-0 mt-px opacity-60">ΓÜá</span>
              <span>{error ?? notice}</span>
            </div>
          )}

          {step.kind === 'password' ? (
            <form
              className="space-y-4"
              onSubmit={(e) => {
                e.preventDefault()
                const form = e.target as HTMLFormElement
                const emailInput = form.elements.namedItem('email') as HTMLInputElement
                const passwordInput = form.elements.namedItem('password') as HTMLInputElement
                void handleSignIn(emailInput.value, passwordInput.value)
              }}
            >
              <Input
                name="email"
                type="email"
                required
                dir="ltr"
                label={t('auth.email')}
                disabled={isLoading}
              />
              <Input
                name="password"
                type="password"
                required
                dir="ltr"
                label={t('auth.password')}
                disabled={isLoading}
              />
              <Button type="submit" fullWidth loading={isLoading}>
                {t('auth.signIn')}
              </Button>
            </form>
          ) : (
            <form
              className="space-y-4"
              onSubmit={(e) => {
                e.preventDefault()
                const form = e.target as HTMLFormElement
                const codeInput = form.elements.namedItem('code') as HTMLInputElement
                void handleVerify(step.factorId, codeInput.value)
              }}
            >
              {step.kind === 'enroll' && (
                <div className="space-y-3">
                  <p className="text-sm text-[hsl(var(--fg-secondary))]">
                    {t('adminPanel.mfaEnrollHint')}
                  </p>
                  {/* Supabase returns the QR as an SVG data URI. */}
                  <img
                    src={step.qrCode}
                    alt={t('adminPanel.mfaQrAlt')}
                    className="mx-auto h-44 w-44 rounded-lg bg-white p-2"
                  />
                  <p className="text-xs text-[hsl(var(--fg-tertiary))]">
                    {t('adminPanel.mfaSecret')}
                  </p>
                  <p
                    dir="ltr"
                    className="break-all rounded-lg bg-[hsl(var(--surface-muted))] p-2 text-center font-mono text-xs"
                  >
                    {step.secret}
                  </p>
                </div>
              )}
              <Input
                name="code"
                required
                dir="ltr"
                inputMode="numeric"
                autoComplete="one-time-code"
                maxLength={6}
                pattern="[0-9]{6}"
                label={t('adminPanel.mfaCode')}
                disabled={isLoading}
              />
              <Button type="submit" fullWidth loading={isLoading}>
                {t('adminPanel.mfaVerify')}
              </Button>
            </form>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

