// ============================================
// apps/admin/app/[lang]/wall/wall-client.tsx
//
// V63 ┬╖ M-6 ΓÇö the television. A TV has no admin session and cannot hold MFA,
// so this page's only credential is a wall token: read-only, expiring,
// revocable, bound to aggregate counts. It reaches nothing else.
//
// The token arrives once in the address, is kept in memory here, and is sent
// as `x-wall-token` on every poll. It is never written to localStorage.
// ============================================

import { useEffect, useState } from 'react'
import { useTranslations } from 'next-intl'
import { Button, Card, CardContent, Input, Label } from '@/components/ui'
import { useAdminLocale } from '@/hooks/use-admin-locale'
import { adminNumber, UNKNOWN_VALUE } from '@/lib/admin-format'
import type { MonitorSnapshot } from '@/hooks/use-admin-monitor'

const POLL_MS = 10_000

function formatBytes(value: number | null): string {
  if (value === null || !Number.isFinite(value)) return UNKNOWN_VALUE
  const units = ['B', 'KB', 'MB', 'GB', 'TB']
  let size = value
  let unit = 0
  while (size >= 1024 && unit < units.length - 1) {
    size /= 1024
    unit += 1
  }
  return `${size.toFixed(unit === 0 ? 0 : 1)} ${units[unit]}`
}

export function WallClient() {
  const t = useTranslations()
  const locale = useAdminLocale()
  const [token, setToken] = useState('')
  const [entry, setEntry] = useState('')
  const [snapshot, setSnapshot] = useState<MonitorSnapshot | null>(null)
  const [invalid, setInvalid] = useState(false)

  // The address carries the token once. Read it after mount so this page needs
  // no Suspense boundary and never renders a token into the HTML.
  useEffect(() => {
    const fromUrl = new URLSearchParams(window.location.search).get('token')
    if (fromUrl && fromUrl.length >= 20) setToken(fromUrl)
  }, [])

  useEffect(() => {
    if (token === '') return
    let cancelled = false

    const load = async () => {
      const base = process.env.NEXT_PUBLIC_API_URL ?? ''
      try {
        const response = await fetch(`${base}/api/wall/overview`, {
          headers: { 'x-wall-token': token },
          cache: 'no-store',
        })
        if (cancelled) return
        if (!response.ok) {
          setInvalid(true)
          setSnapshot(null)
          return
        }
        setInvalid(false)
        setSnapshot((await response.json()) as MonitorSnapshot)
      } catch {
        if (!cancelled) setInvalid(true)
      }
    }

    void load()
    const timer = setInterval(() => void load(), POLL_MS)
    return () => {
      cancelled = true
      clearInterval(timer)
    }
  }, [token])

  if (token === '') {
    return (
      <div className="flex min-h-screen items-center justify-center bg-background p-6">
        <Card className="w-full max-w-md">
          <CardContent className="space-y-4 pt-6">
            <div className="space-y-1 text-start">
              <h1 className="text-lg font-semibold text-foreground">
                {t('admin.operations.monitor.wallTitle')}
              </h1>
              <p className="text-sm text-muted-foreground">
                {t('admin.operations.monitor.wallTokenPrompt')}
              </p>
            </div>
            <div className="space-y-1">
              <Label htmlFor="wall-token">{t('admin.operations.monitor.tokenLabel')}</Label>
              <Input
                id="wall-token"
                dir="ltr"
                autoComplete="off"
                value={entry}
                onChange={(event) => setEntry(event.target.value)}
              />
            </div>
            <Button
              className="w-full"
              disabled={entry.trim().length < 20}
              onClick={() => setToken(entry.trim())}
            >
              {t('admin.operations.monitor.wallOpen')}
            </Button>
          </CardContent>
        </Card>
      </div>
    )
  }

  if (invalid) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-background p-6">
        <Card className="w-full max-w-md">
          <CardContent className="space-y-3 pt-6 text-center">
            <h1 className="text-lg font-semibold text-foreground">
              {t('admin.operations.monitor.wallTokenInvalid')}
            </h1>
            <Button
              variant="outline"
              onClick={() => {
                setToken('')
                setEntry('')
                setInvalid(false)
              }}
            >
              {t('admin.operations.monitor.tokenLabel')}
            </Button>
          </CardContent>
        </Card>
      </div>
    )
  }

  const overview = snapshot?.overview
  const vitals = snapshot?.vitals
  const alerts = snapshot?.alerts ?? []

  return (
    <div className="min-h-screen bg-background p-6">
      <header className="mb-6 flex flex-wrap items-end justify-between gap-3">
        <div>
          <h1 className="text-2xl font-semibold text-foreground">
            {t('admin.operations.monitor.wallTitle')}
          </h1>
          <p className="text-sm text-muted-foreground">
            {t('admin.operations.monitor.wallSubtitle')}
          </p>
        </div>
        {overview && (
          <p className="font-mono text-xs text-muted-foreground" dir="ltr">
            {overview.generatedAt}
          </p>
        )}
      </header>

      <div className="grid grid-cols-2 gap-4 lg:grid-cols-6">
        <Big
          label={t('admin.operations.monitor.onlineUsers')}
          value={overview ? adminNumber(overview.onlineUsers, locale) : UNKNOWN_VALUE}
        />
        <Big
          label={t('admin.operations.monitor.onlineWorkspaces')}
          value={overview ? adminNumber(overview.onlineWorkspaces, locale) : UNKNOWN_VALUE}
        />
        <Big
          label={t('admin.operations.monitor.requests')}
          value={overview ? adminNumber(overview.requests, locale) : UNKNOWN_VALUE}
        />
        <Big
          label={t('admin.operations.monitor.errorRate')}
          value={
            overview && overview.requests > 0
              ? `${((overview.errors5xx / overview.requests) * 100).toFixed(2)}%`
              : UNKNOWN_VALUE
          }
        />
        <Big
          label={t('admin.operations.monitor.bandwidth')}
          value={overview ? formatBytes(overview.bytesOut) : UNKNOWN_VALUE}
        />
        <Big
          label={t('admin.operations.monitor.instancesOnline')}
          value={overview ? adminNumber(overview.instances.length, locale) : UNKNOWN_VALUE}
        />
      </div>

      <div className="mt-6 grid grid-cols-1 gap-6 xl:grid-cols-3">
        <Card>
          <CardContent className="pt-6">
            <h2 className="mb-3 text-sm font-semibold text-foreground">
              {t('admin.operations.monitor.instances')}
            </h2>
            <ul className="space-y-2">
              {(overview?.instances ?? []).map((instance) => (
                <li key={instance.instanceId} className="rounded-lg border border-border p-2">
                  <p dir="ltr" className="font-mono text-xs text-foreground">
                    {instance.instanceId}
                  </p>
                  <p dir="ltr" className="mt-1 font-mono text-xs text-muted-foreground">
                    CPU {instance.cpuPercent.toFixed(1)}% ┬╖ RAM {instance.memoryPercent.toFixed(1)}% ┬╖
                    loop {instance.eventLoopP99Ms.toFixed(0)} ms
                  </p>
                </li>
              ))}
              {(overview?.instances ?? []).length === 0 && (
                <li className="text-sm text-muted-foreground">
                  {t('admin.operations.monitor.noInstances')}
                </li>
              )}
            </ul>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="pt-6">
            <h2 className="mb-3 text-sm font-semibold text-foreground">
              {t('admin.operations.monitor.dbTitle')}
            </h2>
            {vitals?.available ? (
              <dl className="space-y-2 text-sm">
                <Row label={t('admin.operations.monitor.dbSize')} value={formatBytes(vitals.databaseSizeBytes)} />
                <Row
                  label={t('admin.operations.monitor.connections')}
                  value={
                    vitals.connections
                      ? `${vitals.connections.total} / ${vitals.connections.max}`
                      : UNKNOWN_VALUE
                  }
                />
                <Row
                  label={t('admin.operations.monitor.cacheHit')}
                  value={
                    vitals.cacheHitRatio === null
                      ? UNKNOWN_VALUE
                      : `${(vitals.cacheHitRatio * 100).toFixed(2)}%`
                  }
                />
                <Row
                  label={t('admin.operations.monitor.replicationLag')}
                  value={
                    vitals.replicationLagSeconds === null
                      ? t('admin.operations.monitor.noReplica')
                      : `${vitals.replicationLagSeconds} s`
                  }
                />
              </dl>
            ) : (
              <p className="text-sm text-muted-foreground">
                {vitals?.reason ?? t('admin.operations.monitor.dbUnavailable')}
              </p>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardContent className="pt-6">
            <h2 className="mb-3 text-sm font-semibold text-foreground">
              {t('admin.operations.monitor.alerts')}
            </h2>
            <ul className="space-y-2">
              {alerts
                .filter((row) => row.state !== 'ok' && row.state !== 'disabled')
                .map((row) => (
                  <li key={row.rule.id} className="rounded-lg border border-border p-2 text-sm">
                    <span dir="ltr" className="font-mono text-xs text-foreground">
                      {row.rule.metric}
                    </span>{' '}
                    ΓÇö {row.state}
                  </li>
                ))}
              {alerts.filter((row) => row.state !== 'ok' && row.state !== 'disabled').length === 0 && (
                <li className="text-sm text-muted-foreground">
                  {t('admin.operations.monitor.noAlerts')}
                </li>
              )}
            </ul>
          </CardContent>
        </Card>
      </div>

      <div className="mt-6 grid grid-cols-1 gap-6 xl:grid-cols-2">
        <TopList
          title={t('admin.operations.monitor.topByTime')}
          rows={(overview?.topRoutesByTime ?? []).map((row) => ({
            key: `${row.method}-${row.route}`,
            label: `${row.method} ${row.route}`,
            value: `${adminNumber(row.totalMs ?? 0, locale)} ms`,
          }))}
          empty={t('admin.operations.monitor.noTraffic')}
        />
        <TopList
          title={t('admin.operations.monitor.topByBytes')}
          rows={(overview?.topRoutesByBytes ?? []).map((row) => ({
            key: `${row.method}-${row.route}`,
            label: `${row.method} ${row.route}`,
            value: formatBytes(row.bytes ?? null),
          }))}
          empty={t('admin.operations.monitor.noTraffic')}
        />
      </div>
    </div>
  )
}

function Big({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-xl border border-border bg-card p-4">
      <p className="text-xs text-muted-foreground">{label}</p>
      <p dir="ltr" className="mt-1 font-mono text-3xl font-semibold tabular-nums text-foreground">
        {value}
      </p>
    </div>
  )
}

function Row({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-center justify-between gap-3">
      <dt className="text-muted-foreground">{label}</dt>
      <dd dir="ltr" className="font-mono tabular-nums text-foreground">
        {value}
      </dd>
    </div>
  )
}

function TopList({
  title,
  rows,
  empty,
}: {
  title: string
  rows: Array<{ key: string; label: string; value: string }>
  empty: string
}) {
  return (
    <Card>
      <CardContent className="pt-6">
        <h2 className="mb-3 text-sm font-semibold text-foreground">{title}</h2>
        {rows.length === 0 ? (
          <p className="text-sm text-muted-foreground">{empty}</p>
        ) : (
          <ul className="space-y-2">
            {rows.map((row) => (
              <li key={row.key} className="flex items-center justify-between gap-3 text-sm">
                <span dir="ltr" className="truncate font-mono text-xs text-foreground">
                  {row.label}
                </span>
                <span dir="ltr" className="font-mono text-xs tabular-nums text-muted-foreground">
                  {row.value}
                </span>
              </li>
            ))}
          </ul>
        )}
      </CardContent>
    </Card>
  )
}

'use client'

// ┬½Write with AI┬╗ ΓÇö the one-click article of the blog editor.
//
// One button, one dialog: the topic, the EDITORIAL PROMPT (editable, saved for
// every admin, resettable to the default), and the progress of the existing
// content pipeline (research ΓåÆ brief ΓåÆ draft ΓåÆ quality gate).
//
// ΓÜá∩╕Å IT FILLS THE FORM. IT NEVER SAVES AND NEVER PUBLISHES. What comes back is
// handed to the editor as field values; the article's status is untouched, so
// a person still reads it and presses ┬½save┬╗ or ┬½publish┬╗ themselves.
//
// ΓÜá∩╕Å Every failure says WHICH stage and WHY (the server's own reason). A
// pipeline that is not set up ΓÇö no AI provider, the content-intelligence
// scripts not run ΓÇö is said in words, not shown as an endless spinner.
import { useEffect, useState } from 'react'
import { useTranslations } from 'next-intl'
import { Sparkles } from 'lucide-react'
import { apiErrorMessage } from '@hisabche/api'
import type { BlogLocale } from '@hisabche/validation'

import {
  Button,
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  Input,
} from '@/components/ui'
import {
  AiArticleError,
  useGenerateArticle,
  useResetWriterPrompt,
  useSaveWriterPrompt,
  useWriterPrompt,
  type AiStage,
  type GeneratedArticle,
} from '@/hooks/use-admin-blog-ai'

const WORKING: readonly AiStage[] = ['research', 'brief', 'writing', 'checking']

/** Refusals of the pipeline that have their own sentence. Anything else is shown as sent. */
const KNOWN_REASONS = [
  'AI_NOT_CONFIGURED',
  'BLOG_MIGRATION_PENDING',
  'RESEARCH_NOT_CONFIGURED',
  'timeout',
  'cancelled',
] as const

export function AiArticleButton({
  locale,
  topic,
  onApply,
}: {
  locale: BlogLocale
  /** The title already typed, offered as the topic. */
  topic: string
  onApply: (article: GeneratedArticle) => void
}) {
  const t = useTranslations()
  const [open, setOpen] = useState(false)
  const [subject, setSubject] = useState('')
  const [prompt, setPrompt] = useState('')
  const [showPrompt, setShowPrompt] = useState(false)
  const [failure, setFailure] = useState<string | null>(null)
  const [result, setResult] = useState<GeneratedArticle | null>(null)

  const stored = useWriterPrompt(open)
  const savePrompt = useSaveWriterPrompt()
  const resetPrompt = useResetWriterPrompt()
  const { stage, generate, cancel } = useGenerateArticle()
  const working = WORKING.includes(stage)

  // Load the prompt in force into the textarea once it arrives.
  useEffect(() => {
    if (stored.data) setPrompt(stored.data.prompt)
  }, [stored.data])

  const openDialog = () => {
    setSubject(topic.trim())
    setFailure(null)
    setResult(null)
    setOpen(true)
  }

  const explain = (error: unknown): string => {
    const detail =
      error instanceof AiArticleError
        ? error.detail
        : apiErrorMessage(error, t('admin.blog.ai.failed'))
    const known = KNOWN_REASONS.find((code) => (detail ?? '').includes(code))
    const reason = known
      ? t(`admin.blog.ai.reasons.${known}`)
      : (detail ?? t('admin.blog.ai.failed'))
    return error instanceof AiArticleError
      ? `${t(`admin.blog.ai.stage.${error.stage}`)} ΓÇö ${reason}`
      : reason
  }

  const promptDirty = stored.data ? prompt.trim() !== stored.data.prompt.trim() : false

  const run = async () => {
    setFailure(null)
    setResult(null)
    try {
      // The pipeline reads the SAVED prompt: an edited one is saved first, so
      // what is on screen is what writes the article.
      if (promptDirty) await savePrompt.mutateAsync(prompt)
      setResult(await generate(subject.trim(), locale))
    } catch (error) {
      setFailure(explain(error))
    }
  }

  return (
    <>
      <Button type="button" variant="outline" size="sm" onClick={openDialog}>
        <Sparkles className="size-4" aria-hidden="true" />
        {t('admin.blog.ai.button')}
      </Button>

      <Dialog
        open={open}
        onOpenChange={(next) => {
          if (!next && working) cancel()
          setOpen(next)
        }}
      >
        <DialogContent className="max-h-[90vh] max-w-2xl overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{t('admin.blog.ai.title')}</DialogTitle>
            <DialogDescription>{t('admin.blog.ai.description')}</DialogDescription>
          </DialogHeader>

          <label className="block space-y-1">
            <span className="text-xs text-muted-foreground">{t('admin.blog.ai.topic')}</span>
            <Input
              name="topic"
              value={subject}
              maxLength={200}
              disabled={working}
              onChange={(event) => setSubject(event.target.value)}
            />
          </label>

          <div className="space-y-2">
            <button
              type="button"
              className="text-xs text-[hsl(var(--color-primary))] underline"
              onClick={() => setShowPrompt((value) => !value)}
            >
              {showPrompt ? t('admin.blog.ai.hidePrompt') : t('admin.blog.ai.editPrompt')}
              {stored.data && !stored.data.isDefault ? ` ┬╖ ${t('admin.blog.ai.customPrompt')}` : ''}
            </button>
            {showPrompt ? (
              stored.isError ? (
                <p role="alert" className="text-xs text-destructive">
                  {apiErrorMessage(stored.error, t('admin.blog.ai.promptLoadFailed'))}
                </p>
              ) : (
                <>
                  <textarea
                    name="prompt"
                    dir="ltr"
                    rows={14}
                    value={prompt}
                    maxLength={stored.data?.maxLength ?? 20000}
                    disabled={working || stored.isLoading}
                    onChange={(event) => setPrompt(event.target.value)}
                    className="w-full rounded-lg border border-border bg-background p-2 font-mono text-xs"
                  />
                  <p className="text-xs text-muted-foreground">{t('admin.blog.ai.promptHint')}</p>
                  <div className="flex flex-wrap gap-2">
                    <Button
                      type="button"
                      size="sm"
                      variant="outline"
                      disabled={working || !promptDirty || savePrompt.isPending}
                      onClick={() => savePrompt.mutate(prompt)}
                    >
                      {t('admin.blog.ai.savePrompt')}
                    </Button>
                    <Button
                      type="button"
                      size="sm"
                      variant="outline"
                      disabled={
                        working || resetPrompt.isPending || stored.data?.isDefault !== false
                      }
                      onClick={() => resetPrompt.mutate()}
                    >
                      {t('admin.blog.ai.resetPrompt')}
                    </Button>
                  </div>
                  {savePrompt.isError || resetPrompt.isError ? (
                    <p role="alert" className="text-xs text-destructive">
                      {explain(savePrompt.error ?? resetPrompt.error)}
                    </p>
                  ) : savePrompt.isSuccess && !promptDirty ? (
                    <p role="status" className="text-xs text-success">
                      {t('admin.blog.ai.promptSaved')}
                    </p>
                  ) : null}
                </>
              )
            ) : null}
          </div>

          {working ? (
            <p role="status" className="rounded-lg bg-accent p-3 text-sm">
              {t(`admin.blog.ai.stage.${stage}`)}ΓÇª
              <span className="block text-xs text-muted-foreground">
                {t('admin.blog.ai.patience')}
              </span>
            </p>
          ) : null}

          {failure ? (
            <p role="alert" className="rounded-lg bg-destructive/10 p-3 text-sm text-destructive">
              {failure}
            </p>
          ) : null}

          {result ? <Review article={result} /> : null}

          <div className="flex flex-wrap justify-end gap-2">
            {result ? (
              <Button
                type="button"
                onClick={() => {
                  onApply(result)
                  setOpen(false)
                }}
              >
                {t('admin.blog.ai.apply')}
              </Button>
            ) : null}
            <Button
              type="button"
              variant={result ? 'outline' : 'default'}
              disabled={working || subject.trim().length < 3}
              onClick={() => void run()}
            >
              {result ? t('admin.blog.ai.again') : t('admin.blog.ai.generate')}
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </>
  )
}

/** What came back, before it touches the form: the gate's findings and the writer's own gaps. */
function Review({ article }: { article: GeneratedArticle }) {
  const t = useTranslations()
  const failed = article.checks.filter((check) => !check.passed)

  return (
    <div className="space-y-2 rounded-lg border border-border p-3 text-sm" data-ai-review="">
      <p className="font-medium">{article.title}</p>
      <p className="text-xs text-muted-foreground">
        {article.gatePassed === false
          ? t('admin.blog.ai.gateFailed')
          : t('admin.blog.ai.gatePassed', {
              passed: article.checks.length - failed.length,
              total: article.checks.length,
            })}
      </p>
      {failed.length > 0 ? (
        <ul className="space-y-1 text-xs">
          {failed.map((check) => (
            <li key={check.id} className={check.blocking ? 'text-destructive' : 'text-warning'}>
              {check.blocking ? 'Γ£ò' : '!'} <span dir="ltr">{check.id}</span>: {check.reason}
            </li>
          ))}
        </ul>
      ) : null}
      {article.qualityNotes.length > 0 ? (
        <div className="text-xs">
          <p className="font-medium">{t('admin.blog.ai.notes')}</p>
          <ul className="list-disc ps-4">
            {article.qualityNotes.map((note) => (
              <li key={note}>{note}</li>
            ))}
          </ul>
        </div>
      ) : null}
      <p className="text-xs text-muted-foreground">{t('admin.blog.ai.draftOnly')}</p>
    </div>
  )
}

'use client'

// Create or edit one article. The server is the authority on everything it
// can check ΓÇö slug uniqueness, alt text, sanitised HTML, the publication
// rule ΓÇö and its answers land on the field they belong to.
